/// Raven `TeleportToWP`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:716-758`
pub fn TeleportToWP(ctx: GameContext<'_>, pl: *mut gentity_t, afterindex: c_int) {
    unsafe {
        let w = ctx.world;
        if pl.is_null() || (*pl).client.is_null() {
            return;
        }

        let mut foundindex: c_int = 0;
        let mut foundanindex = 0;
        let mut i: c_int = 0;

        if afterindex < 0 || afterindex >= (*w).globals.gWPNum {
            G_Printf(ctx, c"^3Waypoint number %i does not exist\n".as_ptr());
            return;
        }

        while i < (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            if !p.is_null() && (*p).inuse != 0 && (*p).index == afterindex {
                foundindex = i;
                foundanindex = 1;
                break;
            }
            i += 1;
        }

        if foundanindex == 0 {
            G_Printf(ctx, c"^3Waypoint index %i should exist, but does not (?)\n".as_ptr());
            return;
        }

        let cl = (*pl).client as *mut gclient_t;
        (*cl).ps.origin = (*(*w).globals.gWPArray.0[foundindex as usize]).origin;
    }
}

/// Raven `WPFlagsModify`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:760-769`
pub fn WPFlagsModify(ctx: GameContext<'_>, wpnum: c_int, flags: c_int) {
    unsafe {
        let w = ctx.world;
        let p = if wpnum >= 0 && wpnum < (*w).globals.gWPNum {
            (*w).globals.gWPArray.0[wpnum as usize]
        } else {
            core::ptr::null_mut()
        };

        if wpnum < 0 || wpnum >= (*w).globals.gWPNum || p.is_null() || (*p).inuse == 0 {
            G_Printf(ctx, c"^3WPFlagsModify: Waypoint %i does not exist\n".as_ptr());
            return;
        }

        (*p).flags = flags;
    }
}

/// Raven `NotWithinRange` (file-static).
///
/// Pure integer range check — no globals, no traps.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:771-784`
pub fn NotWithinRange(base: c_int, extent: c_int) -> c_int {
    if extent > base && base + 5 >= extent {
        return 0;
    }
    if extent < base && base - 5 <= extent {
        return 0;
    }
    1
}

/// Raven `NodeHere`.
///
/// Whether a node already sits at (integer-truncated) `spot` X/Y with Z within
/// ±5. `spot` is read-only (fork-9: by-value).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:787-809`
pub fn NodeHere(ctx: GameContext<'_>, spot: vec3_t) -> c_int {
    unsafe {
        let w = ctx.world;
        let sx = spot[0] as c_int;
        let sy = spot[1] as c_int;
        let sz = spot[2] as c_int;
        let mut i: c_int = 0;

        while i < (*w).globals.nodenum {
            let o = (*w).globals.nodetable.0[i as usize].origin;
            let nx = o[0] as c_int;
            let ny = o[1] as c_int;
            let nz = o[2] as c_int;
            if nx == sx && ny == sy {
                if nz == sz || (nz < sz && nz + 5 > sz) || (nz > sz && nz - 5 < sz) {
                    return 1;
                }
            }
            i += 1;
        }

        0
    }
}

/// Raven `CanGetToVector`.
///
/// Single solid box-trace between two points; no file-scope state. `org1`/
/// `org2`/`mins`/`maxs` are read-only trace args (never written), so they
/// stay by-value `vec3_t` (fork-9: keep-by-value when never written).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:812-824`
pub fn CanGetToVector(
    ctx: GameContext<'_>,org1: vec3_t, org2: vec3_t, mins: vec3_t, maxs: vec3_t) -> c_int {
    // `ENTITYNUM_NONE` comes from `mp_qshared::shared::limits` (prelude glob).
    unsafe {
        let mut tr: trace_t = core::mem::zeroed();
        trap::Trace(
            ctx.engine,
            GTraceArgs::new(&mut tr, &org1, &mins, &maxs, &org2, ENTITYNUM_NONE, MASK_SOLID),
        );

        if tr.fraction == 1.0 && tr.startsolid == 0 && tr.allsolid == 0 {
            return 1;
        }
    }
    0
}

/// Raven `CanGetToVectorTravel`.
///
/// Walks a box from `org1` toward `moveTo` in `stepSize` increments, allowing a
/// single 16-unit stair step, and reports whether any progress was made. All
/// four `vec3_t` args are read-only (fork-9: by-value). (The `#if 0` block at
/// `ai_wpnav.c:826-882` is dead source, dropped per §20.)
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:883-996`
pub fn CanGetToVectorTravel(
    ctx: GameContext<'_>,
    org1: vec3_t,
    moveTo: vec3_t,
    mins: vec3_t,
    maxs: vec3_t,
) -> c_int {
    unsafe {
        let mut tr: trace_t = core::mem::zeroed();
        let mut step_size: f32 = 0.0;
        let mut did_move: c_int = 0;
        let trace_mask = MASK_PLAYERSOLID;
        let mut initial_done = false;

        let mut working_org: vec3_t = org1;
        let mut last_increment: vec3_t = org1;

        let mut step_to: vec3_t = moveTo;
        step_to[2] = working_org[2];

        let mut step_sub: vec3_t = [
            step_to[0] - working_org[0],
            step_to[1] - working_org[1],
            step_to[2] - working_org[2],
        ];
        step_size = VectorLength(step_sub); // length of the XY-levelled delta
        crate::q_math::VectorNormalize(&mut step_sub);

        while !initial_done || did_move != 0 {
            initial_done = true;
            did_move = 0;

            let step_goal: vec3_t = [
                working_org[0] + step_sub[0] * step_size,
                working_org[1] + step_sub[1] * step_size,
                working_org[2] + step_sub[2] * step_size,
            ];

            wp_trace(ctx, &mut tr, &working_org, &mins, &maxs, &step_goal, ENTITYNUM_NONE, trace_mask);

            if tr.startsolid == 0 && tr.allsolid == 0 && tr.fraction != 0.0 {
                let vec_sub: vec3_t = [
                    working_org[0] - tr.endpos[0],
                    working_org[1] - tr.endpos[1],
                    working_org[2] - tr.endpos[2],
                ];
                if VectorLength(vec_sub) > step_size / 2.0 {
                    working_org[0] = tr.endpos[0];
                    working_org[1] = tr.endpos[1];
                    did_move = 1;
                }
            }

            if did_move != 1 {
                // stair check
                let mut tr_from: vec3_t = tr.endpos;
                tr_from[2] += 16.0;

                let mut tr_dir: vec3_t = [
                    step_goal[0] - working_org[0],
                    step_goal[1] - working_org[1],
                    step_goal[2] - working_org[2],
                ];
                crate::q_math::VectorNormalize(&mut tr_dir);

                let mut tr_to: vec3_t = [
                    tr.endpos[0] + tr_dir[0] * 2.0,
                    tr.endpos[1] + tr_dir[1] * 2.0,
                    tr.endpos[2] + tr_dir[2] * 2.0,
                ];
                tr_to[2] += 16.0;

                let vec_measure: vec3_t = [
                    tr_from[0] - tr_to[0],
                    tr_from[1] - tr_to[1],
                    tr_from[2] - tr_to[2],
                ];

                if VectorLength(vec_measure) > 1.0 {
                    wp_trace(ctx, &mut tr, &tr_from, &mins, &maxs, &tr_to, ENTITYNUM_NONE, trace_mask);

                    if tr.startsolid == 0 && tr.allsolid == 0 && tr.fraction == 1.0 {
                        // clear trace here, probably up a step
                        let _tr_up: vec3_t = tr.endpos;
                        let mut tr_down: vec3_t = tr.endpos;
                        tr_down[2] -= 16.0;

                        wp_trace(ctx, &mut tr, &tr_from, &mins, &maxs, &tr_to, ENTITYNUM_NONE, trace_mask);

                        if tr.startsolid == 0 && tr.allsolid == 0 {
                            working_org = tr.endpos;
                            did_move = 1;
                        }
                    }
                }
            }

            let final_measure: vec3_t = [
                last_increment[0] - working_org[0],
                last_increment[1] - working_org[1],
                last_increment[2] - working_org[2],
            ];
            let measure_length = VectorLength(final_measure);

            if measure_length == 0.0 {
                break; // no progress
            }

            step_size -= measure_length;
            if step_size <= 0.0 {
                break;
            }

            last_increment = working_org;
        }

        did_move
    }
}

/// Raven `ConnectTrail`.
///
/// Branch-searches the node grid from `startindex` to `endindex`, then walks
/// the found chain back inserting waypoints. Falls back to a one-way flag pair
/// when unreachable. (The `g_RMG` short-circuit at the top means the inner
/// `g_RMG` branch-distance block is only reached when `g_RMG` is off; it is
/// transcribed faithfully regardless.)
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1000-1399`
pub fn ConnectTrail(
    ctx: GameContext<'_>,
    startindex: c_int,
    endindex: c_int,
    behindTheScenes: qboolean,
) -> c_int {
    // Try to drop one branch node offset by (dx,dy) from node `i`; returns true
    // when a node was appended (sets `cancontinue`). Mirrors the four repeated
    // X±/Y± blocks in the oracle.
    unsafe fn branch_dir(
        ctx: GameContext<'_>,
        i: c_int,
        dx: f32,
        dy: f32,
        base_height: f32,
        mins: vec3_t,
        maxs: vec3_t,
    ) -> bool {
        let w = ctx.world;
        let mut testspot = (*w).globals.nodetable.0[i as usize].origin;
        testspot[0] += dx;
        testspot[1] += dy;

        let mut starttrace = testspot;
        starttrace[2] -= 4096.0;

        let mut tr: trace_t = core::mem::zeroed();
        wp_trace(
            ctx,
            &mut tr,
            &testspot,
            core::ptr::null(),
            core::ptr::null(),
            &starttrace,
            ENTITYNUM_NONE,
            MASK_SOLID,
        );

        testspot[2] = tr.endpos[2] + base_height;

        let src = (*w).globals.nodetable.0[i as usize].origin;
        if NodeHere(ctx, testspot) == 0
            && tr.startsolid == 0
            && tr.allsolid == 0
            && CanGetToVector(ctx, src, testspot, mins, maxs) != 0
        {
            let nn = (*w).globals.nodenum as usize;
            (*w).globals.nodetable.0[nn].origin = testspot;
            (*w).globals.nodetable.0[nn].inuse = 1;
            (*w).globals.nodetable.0[nn].weight = (*w).globals.nodetable.0[i as usize].weight + 1.0;
            (*w).globals.nodetable.0[nn].neighbornum = i;
            if (*w).globals.nodetable.0[i as usize].origin[2] - (*w).globals.nodetable.0[nn].origin[2]
                > 50.0
            {
                // big drop — can't magically fly back up
                (*w).globals.nodetable.0[nn].flags = WPFLAG_ONEWAY_FWD;
            }
            (*w).globals.nodenum += 1;
            return true;
        }
        false
    }

    unsafe {
        let w = ctx.world;
        let mut foundit: c_int = 0;
        let mut cancontinue: c_int;
        let mut i: c_int;
        let mut failsafe: c_int;
        let mut successnodeindex: c_int = 0;
        let insertindex: c_int;
        let mut prenodestart: c_int;
        let mut extendednodes = [0u8; MAX_NODETABLE_SIZE as usize];
        let mut fvecmeas: f32;
        let baseheight: f32;
        let mut branch_distance: f32;
        let mut max_dist_factor: f32 = 256.0;
        let mins: vec3_t = [-15.0, -15.0, 0.0];
        let maxs: vec3_t = [15.0, 15.0, 0.0];

        if (*w).cvars.g_RMG.integer != 0 {
            // this might be temporary. Or not.
            let sp = (*w).globals.gWPArray.0[startindex as usize];
            let ep = (*w).globals.gWPArray.0[endindex as usize];
            if (*sp).flags & WPFLAG_NEVERONEWAY == 0 && (*ep).flags & WPFLAG_NEVERONEWAY == 0 {
                (*sp).flags |= WPFLAG_ONEWAY_FWD;
                (*ep).flags |= WPFLAG_ONEWAY_BACK;
            }
            return 0;
        }

        if (*w).cvars.g_RMG.integer == 0 {
            branch_distance = TABLE_BRANCH_DISTANCE;
        } else {
            branch_distance = 512.0; // be less precise on broad terrain
        }

        if (*w).cvars.g_RMG.integer != 0 {
            max_dist_factor = 700.0;
        }

        (*w).globals.nodenum = 0;
        foundit = 0;
        i = 0;
        successnodeindex = 0;

        // clear the node table before using it
        while i < MAX_NODETABLE_SIZE {
            let nt = &mut (*w).globals.nodetable.0[i as usize];
            nt.flags = 0;
            nt.inuse = 0;
            nt.neighbornum = 0;
            nt.origin = [0.0, 0.0, 0.0];
            nt.weight = 0.0;
            extendednodes[i as usize] = 0;
            i += 1;
        }

        i = 0;

        if behindTheScenes == 0 {
            G_Printf(ctx, c"^3Point %i is not connected to %i - Repairing...\n".as_ptr());
        }

        let startplace = (*(*w).globals.gWPArray.0[startindex as usize]).origin;
        let mut starttrace = startplace;
        starttrace[2] -= 4096.0;

        let mut tr: trace_t = core::mem::zeroed();
        wp_trace(
            ctx,
            &mut tr,
            &startplace,
            core::ptr::null(),
            core::ptr::null(),
            &starttrace,
            ENTITYNUM_NONE,
            MASK_SOLID,
        );

        baseheight = startplace[2] - tr.endpos[2];
        cancontinue = 1;

        {
            let nn = (*w).globals.nodenum as usize;
            (*w).globals.nodetable.0[nn].origin = startplace;
            (*w).globals.nodetable.0[nn].weight = 1.0;
            (*w).globals.nodetable.0[nn].inuse = 1;
            (*w).globals.nodenum += 1;
        }

        while (*w).globals.nodenum < MAX_NODETABLE_SIZE && foundit == 0 && cancontinue != 0 {
            if (*w).cvars.g_RMG.integer != 0 {
                // adjust branch distance by distance from start/end (RMG only)
                let last = ((*w).globals.nodenum - 1) as usize;
                let so = (*(*w).globals.gWPArray.0[startindex as usize]).origin;
                let eo = (*(*w).globals.gWPArray.0[endindex as usize]).origin;
                let no = (*w).globals.nodetable.0[last].origin;
                let start_distf = VectorLength([no[0] - so[0], no[1] - so[1], no[2] - so[2]]);
                let end_distf = VectorLength([no[0] - eo[0], no[1] - eo[1], no[2] - eo[2]]);
                if start_distf < 64.0 || end_distf < 64.0 {
                    branch_distance = 64.0;
                } else if start_distf < 128.0 || end_distf < 128.0 {
                    branch_distance = 128.0;
                } else if start_distf < 256.0 || end_distf < 256.0 {
                    branch_distance = 256.0;
                } else if start_distf < 512.0 || end_distf < 512.0 {
                    branch_distance = 512.0;
                } else {
                    branch_distance = 800.0;
                }
            }

            cancontinue = 0;
            i = 0;
            prenodestart = (*w).globals.nodenum;

            while i < prenodestart {
                if extendednodes[i as usize] != 1 {
                    let eo = (*(*w).globals.gWPArray.0[endindex as usize]).origin;
                    let no = (*w).globals.nodetable.0[i as usize].origin;
                    fvecmeas = VectorLength([eo[0] - no[0], eo[1] - no[1], eo[2] - no[2]]);

                    if fvecmeas < 128.0 && CanGetToVector(ctx, eo, no, mins, maxs) != 0 {
                        foundit = 1;
                        successnodeindex = i;
                        break;
                    }

                    if branch_dir(ctx, i, branch_distance, 0.0, baseheight, mins, maxs) {
                        cancontinue = 1;
                    }
                    if (*w).globals.nodenum >= MAX_NODETABLE_SIZE {
                        break;
                    }

                    if branch_dir(ctx, i, -branch_distance, 0.0, baseheight, mins, maxs) {
                        cancontinue = 1;
                    }
                    if (*w).globals.nodenum >= MAX_NODETABLE_SIZE {
                        break;
                    }

                    if branch_dir(ctx, i, 0.0, branch_distance, baseheight, mins, maxs) {
                        cancontinue = 1;
                    }
                    if (*w).globals.nodenum >= MAX_NODETABLE_SIZE {
                        break;
                    }

                    if branch_dir(ctx, i, 0.0, -branch_distance, baseheight, mins, maxs) {
                        cancontinue = 1;
                    }
                    if (*w).globals.nodenum >= MAX_NODETABLE_SIZE {
                        break;
                    }

                    extendednodes[i as usize] = 1;
                }

                i += 1;
            }
        }

        if foundit == 0 {
            // non-debug build: only print when not auto-pathing
            if behindTheScenes == 0 {
                G_Printf(
                    ctx,
                    c"^1Could not link %i to %i, unreachable by node branching.\n".as_ptr(),
                );
            }
            (*(*w).globals.gWPArray.0[startindex as usize]).flags |= WPFLAG_ONEWAY_FWD;
            (*(*w).globals.gWPArray.0[endindex as usize]).flags |= WPFLAG_ONEWAY_BACK;
            if behindTheScenes == 0 {
                G_Printf(
                    ctx,
                    c"^3Since points cannot be connected, point %i has been flagged as only-forward and point %i has been flagged as only-backward.\n".as_ptr(),
                );
            }

            if behindTheScenes == 0 {
                // just use what we have if auto-pathing the level
                return 0;
            } else {
                let mut n_count: c_int = 0;
                let mut ideal_node: c_int = -1;
                let mut best_dist: f32 = 0.0;
                let mut test_dist: f32;

                if (*w).globals.nodenum <= 10 {
                    return 0; // not enough to bother
                }

                // find whichever node is closest to the desired end
                while n_count < (*w).globals.nodenum {
                    let no = (*w).globals.nodetable.0[n_count as usize].origin;
                    let eo = (*(*w).globals.gWPArray.0[endindex as usize]).origin;
                    test_dist = VectorLength([no[0] - eo[0], no[1] - eo[1], no[2] - eo[2]]);
                    if ideal_node == -1 {
                        ideal_node = n_count;
                        best_dist = test_dist;
                        n_count += 1;
                        continue;
                    }

                    if test_dist < best_dist {
                        ideal_node = n_count;
                        best_dist = test_dist;
                    }

                    n_count += 1;
                }

                if ideal_node == -1 {
                    return 0;
                }

                successnodeindex = ideal_node;
            }
        }

        i = successnodeindex;
        insertindex = startindex;
        failsafe = 0;
        let mut validspotpos = (*(*w).globals.gWPArray.0[startindex as usize]).origin;

        while failsafe < MAX_NODETABLE_SIZE && i < MAX_NODETABLE_SIZE && i >= 0 {
            let no = (*w).globals.nodetable.0[i as usize].origin;
            let a = [validspotpos[0] - no[0], validspotpos[1] - no[1], validspotpos[2] - no[2]];
            let neigh = (*w).globals.nodetable.0[i as usize].neighbornum;
            let eo = (*(*w).globals.gWPArray.0[endindex as usize]).origin;

            if (*w).globals.nodetable.0[neigh as usize].inuse == 0
                || CanGetToVectorTravel(ctx, validspotpos, no, mins, maxs) == 0
                || VectorLength(a) > max_dist_factor
                || (CanGetToVectorTravel(ctx, validspotpos, eo, mins, maxs) == 0
                    && CanGetToVectorTravel(ctx, no, eo, mins, maxs) != 0)
            {
                (*w).globals.nodetable.0[i as usize].flags |= WPFLAG_CALCULATED;
                let nf = (*w).globals.nodetable.0[i as usize].flags;
                if CreateNewWP_InTrail(ctx, no, nf, insertindex) == 0 {
                    if behindTheScenes == 0 {
                        G_Printf(
                            ctx,
                            c"^1Could not link %i to %i, waypoint limit hit.\n".as_ptr(),
                        );
                    }
                    return 0;
                }

                validspotpos = no;
            }

            if i == 0 {
                break;
            }

            i = (*w).globals.nodetable.0[i as usize].neighbornum;
            failsafe += 1;
        }

        if behindTheScenes == 0 {
            G_Printf(ctx, c"^3Finished connecting %i to %i.\n".as_ptr());
        }

        1
    }
}

/// Raven `OpposingEnds`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1402-1416`
pub fn OpposingEnds(ctx: GameContext<'_>, start: c_int, end: c_int) -> c_int {
    unsafe {
        let w = ctx.world;
        let sp = (*w).globals.gWPArray.0[start as usize];
        let ep = (*w).globals.gWPArray.0[end as usize];
        if sp.is_null() || (*sp).inuse == 0 || ep.is_null() || (*ep).inuse == 0 {
            return 0;
        }

        if (*sp).flags & WPFLAG_ONEWAY_FWD != 0 && (*ep).flags & WPFLAG_ONEWAY_BACK != 0 {
            return 1;
        }

        0
    }
}

/// Raven `DoorBlockingSection`.
///
/// If a `func_` brush blocks both directions of the segment, treat it as an
/// (openable) door and let the two endpoints stay linked.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1418-1463`
pub fn DoorBlockingSection(ctx: GameContext<'_>, start: c_int, end: c_int) -> c_int {
    unsafe {
        let w = ctx.world;
        let sp = (*w).globals.gWPArray.0[start as usize];
        let ep = (*w).globals.gWPArray.0[end as usize];
        if sp.is_null() || (*sp).inuse == 0 || ep.is_null() || (*ep).inuse == 0 {
            return 0;
        }

        let mut tr: trace_t = core::mem::zeroed();
        let s_org = (*sp).origin;
        let e_org = (*ep).origin;
        wp_trace(
            ctx, &mut tr, &s_org, core::ptr::null(), core::ptr::null(), &e_org,
            ENTITYNUM_NONE, MASK_SOLID,
        );

        if tr.fraction == 1.0 {
            return 0;
        }

        let cn = (*w).entities[tr.entityNum as usize].classname;
        // Raven derefs `testdoor->classname` unconditionally; a slot with a
        // null classname would crash there — the one defined behavior here is
        // "no `func_` match" (returns 0). (§19)
        if cn.is_null() {
            return 0;
        }
        if !c_str_contains(cn, b"func_") {
            return 0;
        }

        let start_trace_index = tr.entityNum;

        wp_trace(
            ctx, &mut tr, &e_org, core::ptr::null(), core::ptr::null(), &s_org,
            ENTITYNUM_NONE, MASK_SOLID,
        );

        if tr.fraction == 1.0 {
            return 0;
        }

        if start_trace_index == tr.entityNum {
            return 1;
        }

        0
    }
}

/// `strstr`-style substring test on a NUL-terminated C string.
unsafe fn c_str_contains(s: *const c_char, needle: &[u8]) -> bool {
    if s.is_null() {
        return false;
    }
    let bytes = core::ffi::CStr::from_ptr(s).to_bytes();
    bytes.windows(needle.len()).any(|w| w == needle)
}

// PORT-ESCALATION(depends-on-parked-OrgVisible): the visibility-connect
// predicate calls `OrgVisible` (parked `todo!()` in `ai_main.rs`); its result
// gates `ConnectTrail`, so it is load-bearing (not a droppable side effect) and
// calling the stub would panic on the happy path. Also reads the `bot_wp_*`
// cvars (cvar-placement). The arena repr this used to block on is now resolved.
