/// Raven `OrgVisibleCurve`.
///
/// Double solid box-trace along a levelled path segment; no file-scope state.
/// All `vec3_t` args are read-only trace args (`org1`/`org2`/`mins`/`maxs`),
/// so they stay by-value (fork-9: keep-by-value when never written).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1526-1547`
pub fn OrgVisibleCurve(
    ctx: GameContext<'_>,org1: vec3_t, mins: vec3_t, maxs: vec3_t, org2: vec3_t, ignore: c_int) -> c_int {
    unsafe {
        let mut tr: trace_t = core::mem::zeroed();
        let mut evenorg1: vec3_t = org1;
        evenorg1[2] = org2[2];

        trap::Trace(
            ctx.engine,
            GTraceArgs::new(&mut tr, &evenorg1, &mins, &maxs, &org2, ignore, MASK_SOLID),
        );

        if tr.fraction == 1.0 && tr.startsolid == 0 && tr.allsolid == 0 {
            trap::Trace(
                ctx.engine,
                GTraceArgs::new(&mut tr, &evenorg1, &mins, &maxs, &org1, ignore, MASK_SOLID),
            );

            if tr.fraction == 1.0 && tr.startsolid == 0 && tr.allsolid == 0 {
                return 1;
            }
        }
    }
    0
}

/// Raven `CanForceJumpTo`.
///
/// Returns a nonzero force-jump "level" (1/2/3) when `testingindex` is a
/// reachable force-jump-up target from `baseindex`, else 0.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1549-1621`
pub fn CanForceJumpTo(
    ctx: GameContext<'_>,
    baseindex: c_int,
    testingindex: c_int,
    distance: f32,
) -> c_int {
    unsafe {
        let w = ctx.world;
        let heightdif: f32;
        let mins: vec3_t = [-15.0, -15.0, -15.0];
        let maxs: vec3_t = [15.0, 15.0, 15.0];
        let wp_base = (*w).globals.gWPArray.0[baseindex as usize];
        let wp_test = (*w).globals.gWPArray.0[testingindex as usize];

        if wp_base.is_null() || (*wp_base).inuse == 0 || wp_test.is_null() || (*wp_test).inuse == 0 {
            return 0;
        }

        if distance > 400.0 {
            return 0;
        }

        let mut xy_base = (*wp_base).origin;
        let xy_test = (*wp_test).origin;
        xy_base[2] = xy_test[2];

        let v = [xy_base[0] - xy_test[0], xy_base[1] - xy_test[1], xy_base[2] - xy_test[2]];
        if VectorLength(v) > MAX_NEIGHBOR_LINK_DISTANCE {
            return 0;
        }

        if ((*wp_base).origin[2] as c_int) < ((*wp_test).origin[2] as c_int) {
            heightdif = (*wp_test).origin[2] - (*wp_base).origin[2];
        } else {
            return 0; // err..
        }

        if heightdif < 128.0 {
            return 0; // don't bother
        }

        if heightdif > 512.0 {
            return 0; // too high
        }

        if OrgVisibleCurve(ctx, (*wp_base).origin, mins, maxs, (*wp_test).origin, ENTITYNUM_NONE) == 0
        {
            return 0;
        }

        if heightdif > 400.0 {
            3
        } else if heightdif > 256.0 {
            2
        } else {
            1
        }
    }
}

