/// Raven `CalculateJumpRoutes`.
///
/// Marks jump waypoints that need force-jumping (999 = "FJSR" sentinel) by the
/// height drop to their trail neighbours.
///
/// The oracle reads `gWPArray[i-1]`/`gWPArray[i+1]` unguarded; at `i==0` that
/// is an out-of-bounds `gWPArray[-1]`, and `i+1` can reach one past the array —
/// the one defined behavior here treats those as null (skip the branch). (§19)
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1953-2005`
pub fn CalculateJumpRoutes(ctx: GameContext<'_>) {
    unsafe {
        let w = ctx.world;
        let mut i: c_int = 0;
        let mut nheightdif: f32;
        let mut pheightdif: f32;

        while i < (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            if !p.is_null() && (*p).inuse != 0 {
                if (*p).flags & WPFLAG_JUMP != 0 {
                    nheightdif = 0.0;
                    pheightdif = 0.0;
                    (*p).forceJumpTo = 0;

                    let prev = if i >= 1 {
                        (*w).globals.gWPArray.0[(i - 1) as usize]
                    } else {
                        core::ptr::null_mut()
                    };
                    if !prev.is_null()
                        && (*prev).inuse != 0
                        && (*prev).origin[2] + 16.0 < (*p).origin[2]
                    {
                        nheightdif = (*p).origin[2] - (*prev).origin[2];
                    }

                    let next = if i + 1 < MAX_WPARRAY_SIZE {
                        (*w).globals.gWPArray.0[(i + 1) as usize]
                    } else {
                        core::ptr::null_mut()
                    };
                    if !next.is_null()
                        && (*next).inuse != 0
                        && (*next).origin[2] + 16.0 < (*p).origin[2]
                    {
                        pheightdif = (*p).origin[2] - (*next).origin[2];
                    }

                    if nheightdif > pheightdif {
                        pheightdif = nheightdif;
                    }

                    if pheightdif != 0.0 {
                        // FJSR: all three force levels collapse to the 999 sentinel
                        if pheightdif > 500.0 {
                            (*p).forceJumpTo = 999;
                        } else if pheightdif > 256.0 {
                            (*p).forceJumpTo = 999;
                        } else if pheightdif > 128.0 {
                            (*p).forceJumpTo = 999;
                        }
                    }
                }
            }

            i += 1;
        }
    }
}

