/// Raven `G_NodeMatchingXY`.
///
/// First unflagged node with matching X/Y (exact float compare, per oracle).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2570-2587`
pub fn G_NodeMatchingXY(ctx: GameContext<'_>, x: f32, y: f32) -> c_int {
    unsafe {
        let w = ctx.world;
        let mut i: c_int = 0;
        while i < (*w).globals.nodenum {
            let nt = &(*w).globals.nodetable.0[i as usize];
            if nt.origin[0] == x && nt.origin[1] == y && nt.flags == 0 {
                return i;
            }
            i += 1;
        }
        -1
    }
}

/// Raven `G_NodeMatchingXY_BA`.
///
/// Lowest-weight unflagged node with matching (int-truncated) X/Y, short-circuit
/// returning `final` if reached.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2589-2614`
pub fn G_NodeMatchingXY_BA(ctx: GameContext<'_>, x: c_int, y: c_int, r#final: c_int) -> c_int {
    unsafe {
        let w = ctx.world;
        let mut i: c_int = 0;
        let mut bestindex: c_int = -1;
        let mut best_weight: f32 = 9999.0;

        while i < (*w).globals.nodenum {
            let nt = &(*w).globals.nodetable.0[i as usize];
            if nt.origin[0] as c_int == x
                && nt.origin[1] as c_int == y
                && nt.flags == 0
                && (nt.weight < best_weight || i == r#final)
            {
                if i == r#final {
                    return i;
                }
                bestindex = i;
                best_weight = nt.weight;
            }
            i += 1;
        }

        bestindex
    }
}

/// Raven `G_RecursiveConnection`.
///
/// Flood-fills weights out from `start` across the 4-connected grid until it
/// reaches `end`, optionally requiring a clear trace between adjacent nodes.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2616-2689`
pub fn G_RecursiveConnection(
    ctx: GameContext<'_>,
    start: c_int,
    end: c_int,
    weight: c_int,
    traceCheck: qboolean,
    baseHeight: f32,
) -> c_int {
    unsafe {
        let w = ctx.world;
        // 0 == down, 1 == up, 2 == left, 3 == right
        let mut index_directions: [c_int; 4] = [-1; 4];
        let mut recursive_index: c_int = -1;
        let mut i: c_int = 0;
        let pass_weight = weight + 1;
        let mut given_xy: [f32; 2];

        (*w).globals.nodetable.0[start as usize].weight = pass_weight as f32;

        let sorg = (*w).globals.nodetable.0[start as usize].origin;

        given_xy = [sorg[0] - DEFAULT_GRID_SPACING, sorg[1]];
        index_directions[0] = G_NodeMatchingXY(ctx, given_xy[0], given_xy[1]);

        given_xy = [sorg[0] + DEFAULT_GRID_SPACING, sorg[1]];
        index_directions[1] = G_NodeMatchingXY(ctx, given_xy[0], given_xy[1]);

        given_xy = [sorg[0], sorg[1] - DEFAULT_GRID_SPACING];
        index_directions[2] = G_NodeMatchingXY(ctx, given_xy[0], given_xy[1]);

        given_xy = [sorg[0], sorg[1] + DEFAULT_GRID_SPACING];
        index_directions[3] = G_NodeMatchingXY(ctx, given_xy[0], given_xy[1]);

        i = 0;
        while i < 4 {
            let d = index_directions[i as usize];
            if d == end {
                // connected all the way to the destination
                return d;
            }

            if d != -1 && (*w).globals.nodetable.0[d as usize].flags != 0 {
                // already used — not valid
                index_directions[i as usize] = -1;
            } else if d != -1 {
                // otherwise mark it as used
                (*w).globals.nodetable.0[d as usize].flags = 1;
            }

            let d = index_directions[i as usize];
            if d != -1 && traceCheck != 0 {
                let mut tr: trace_t = core::mem::zeroed();
                let a = (*w).globals.nodetable.0[start as usize].origin;
                let b = (*w).globals.nodetable.0[d as usize].origin;
                wp_trace(
                    ctx, &mut tr, &a, core::ptr::null(), core::ptr::null(), &b,
                    ENTITYNUM_NONE, CONTENTS_SOLID,
                );
                if tr.fraction != 1.0 {
                    index_directions[i as usize] = -1;
                }
            }

            let d = index_directions[i as usize];
            if d != -1 {
                // still valid — keep connecting via this point
                recursive_index = G_RecursiveConnection(ctx, d, end, pass_weight, traceCheck, baseHeight);
            }

            if recursive_index != -1 {
                return recursive_index;
            }

            i += 1;
        }

        recursive_index
    }
}

/// Raven `G_BackwardAttachment`.
///
/// After a node path exists, walks it back toward `finalDestination` (lowest
/// weight per step), materialising waypoints via `CreateNewWP_InsertUnder`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2981-3048`
pub fn G_BackwardAttachment(
    ctx: GameContext<'_>,
    start: c_int,
    finalDestination: c_int,
    insertAfter: c_int,
) -> qboolean {
    unsafe {
        let w = ctx.world;
        let mut index_directions: [c_int; 4] = [-1; 4];
        let mut i: c_int = 0;
        let mut lowest_weight: c_int = 9999;
        let mut desired_index: c_int = -1;

        let sorg = (*w).globals.nodetable.0[start as usize].origin;

        let mut given_xy: [f32; 2] = [sorg[0] - DEFAULT_GRID_SPACING, sorg[1]];
        index_directions[0] =
            G_NodeMatchingXY_BA(ctx, given_xy[0] as c_int, given_xy[1] as c_int, finalDestination);

        given_xy = [sorg[0] + DEFAULT_GRID_SPACING, sorg[1]];
        index_directions[1] =
            G_NodeMatchingXY_BA(ctx, given_xy[0] as c_int, given_xy[1] as c_int, finalDestination);

        given_xy = [sorg[0], sorg[1] - DEFAULT_GRID_SPACING];
        index_directions[2] =
            G_NodeMatchingXY_BA(ctx, given_xy[0] as c_int, given_xy[1] as c_int, finalDestination);

        given_xy = [sorg[0], sorg[1] + DEFAULT_GRID_SPACING];
        index_directions[3] =
            G_NodeMatchingXY_BA(ctx, given_xy[0] as c_int, given_xy[1] as c_int, finalDestination);

        while i < 4 {
            let d = index_directions[i as usize];
            if d != -1 {
                if d == finalDestination {
                    // found the original point and linked all the way back
                    let a = (*w).globals.nodetable.0[start as usize].origin;
                    CreateNewWP_InsertUnder(ctx, a, 0, insertAfter);
                    let b = (*w).globals.nodetable.0[d as usize].origin;
                    CreateNewWP_InsertUnder(ctx, b, 0, insertAfter);
                    return QTRUE;
                }

                let nt = &(*w).globals.nodetable.0[d as usize];
                if nt.weight < lowest_weight as f32 && nt.weight != 0.0 && nt.flags == 0 {
                    desired_index = d;
                    lowest_weight = nt.weight as c_int;
                }
            }
            i += 1;
        }

        if desired_index != -1 {
            // create a waypoint here, then recurse for the lowest-weight neighbor
            if (*w).globals.gWPNum < 3900 {
                let a = (*w).globals.nodetable.0[start as usize].origin;
                CreateNewWP_InsertUnder(ctx, a, 0, insertAfter);
            } else {
                return QFALSE;
            }

            (*w).globals.nodetable.0[start as usize].flags = 1;
            return G_BackwardAttachment(ctx, desired_index, finalDestination, insertAfter);
        }

        QFALSE
    }
}

