/// Raven `GetClosestSpawn`.
///
/// Nearest spawn entity to `ent`'s player origin (walks only the non-client
/// entity range).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:3425-3457`
pub fn GetClosestSpawn(ctx: GameContext<'_>, ent: *mut gentity_t) -> *mut gentity_t {
    unsafe {
        let w = ctx.world;
        let mut closest_spawn: *mut gentity_t = core::ptr::null_mut();
        let mut closest_dist: f32 = -1.0;
        let mut i: c_int = MAX_CLIENTS as c_int;

        while i < (*w).level.num_entities {
            let spawn: *mut gentity_t = &mut (*w).entities[i as usize];
            if !spawn.is_null()
                && (*spawn).inuse != 0
                && (Q_stricmp((*spawn).classname, c"info_player_start".as_ptr()) == 0
                    || Q_stricmp((*spawn).classname, c"info_player_deathmatch".as_ptr()) == 0)
            {
                let eo = (*((*ent).client as *mut gclient_t)).ps.origin;
                let so = (*spawn).r.currentOrigin;
                let check_dist = VectorLength([eo[0] - so[0], eo[1] - so[1], eo[2] - so[2]]);

                if closest_dist == -1.0 || check_dist < closest_dist {
                    closest_spawn = spawn;
                    closest_dist = check_dist;
                }
            }
            i += 1;
        }

        closest_spawn
    }
}

/// Raven `GetNextSpawnInIndex`.
///
/// Next spawn entity after `currentSpawn` in index order, wrapping back to
/// `MAX_CLIENTS` if none follows.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:3459-3499`
pub fn GetNextSpawnInIndex(
    ctx: GameContext<'_>,
    currentSpawn: *mut gentity_t,
) -> *mut gentity_t {
    unsafe {
        let w = ctx.world;
        let mut next_spawn: *mut gentity_t = core::ptr::null_mut();
        let mut i: c_int = (*currentSpawn).s.number + 1;

        while i < (*w).level.num_entities {
            let spawn: *mut gentity_t = &mut (*w).entities[i as usize];
            if !spawn.is_null()
                && (*spawn).inuse != 0
                && (Q_stricmp((*spawn).classname, c"info_player_start".as_ptr()) == 0
                    || Q_stricmp((*spawn).classname, c"info_player_deathmatch".as_ptr()) == 0)
            {
                next_spawn = spawn;
                break;
            }
            i += 1;
        }

        if next_spawn.is_null() {
            // loop back around to 0 (client range end)
            i = MAX_CLIENTS as c_int;
            while i < (*w).level.num_entities {
                let spawn: *mut gentity_t = &mut (*w).entities[i as usize];
                if !spawn.is_null()
                    && (*spawn).inuse != 0
                    && (Q_stricmp((*spawn).classname, c"info_player_start".as_ptr()) == 0
                        || Q_stricmp((*spawn).classname, c"info_player_deathmatch".as_ptr()) == 0)
                {
                    next_spawn = spawn;
                    break;
                }
                i += 1;
            }
        }

        next_spawn
    }
}

